#[derive(Debug)]
pub struct Surv {
    indicator: usize,
    entry_time: f64,
    exit_l: f64,
    exit_r: f64,
}

impl Surv {
    pub fn new(ind: usize, entry_time: f64, exit_l: f64, exit_r: f64) -> Surv {
        Surv {
            indicator: ind,
            entry_time,
            exit_l,
            exit_r,
        }
    }

    pub fn new_event(ind: usize, entry_time: f64, event_time: f64) -> Surv {
        Surv {
            indicator: ind,
            entry_time,
            exit_l: event_time,
            exit_r: event_time,
        }
    }

    pub fn new_censor(entry_time: f64, event_time: f64) -> Surv {
        Surv {
            indicator: 0,
            entry_time,
            exit_l: event_time,
            exit_r: f64::INFINITY,
        }
    }

    pub fn from_exit_vec(vec: Vec<(f64, usize)>) -> Vec<Surv> {
        vec.iter()
            .map(|(event_time, event_ind)| Surv {
                indicator: *event_ind,
                entry_time: 0.0,
                exit_l: *event_time,
                exit_r: *event_time,
            })
            .collect::<Vec<Surv>>()
    }

    pub fn is_censored(&self) -> bool {
        self.indicator == 0
    }

    pub fn is_interval_censored(&self) -> bool {
        !(self.exit_l == self.exit_r)
    }

    pub fn get_entry_time(&self) -> f64 {
        self.entry_time
    }

    pub fn get_exit_l(&self) -> f64 {
        self.exit_l
    }

    pub fn get_exit_time(&self) -> f64 {
        self.exit_r
    }
}

impl SurvResult {
    pub fn new_result(times_vec: Vec<f64>, density_vec: DVector<f64>) -> Self {
        let mut result_vec = Vec::new();

        if times_vec.len() != density_vec.len() {
            panic!("Length of unique event times does not equal density vector.");
        }

        let mut cumsum = density_vec.clone();
        cumsum.iter_mut().fold(0.0, |acc, x| {
            *x += acc;
            *x
        });

        zip(times_vec.iter(), cumsum.iter()).for_each(|(&t, &d)| {
            result_vec.push((t, 1.0 - d, 0.0));
        });

        SurvResult { times: result_vec }
    }

    pub fn get_survival_table(&self) -> Vec<(f64, f64, f64)> {
        self.times.clone()

pub fn kaplan_meier(events: Vec<Surv>, weights: Option<Vec<f64>>) -> SurvResult {
    let mut unique_event_times = events
        .iter()
        .filter(|&ev| !ev.is_censored() && !ev.is_interval_censored())
        .map(|ev| ev.get_exit_time())
        .collect::<Vec<f64>>();

    unique_event_times.dedup();
    unique_event_times.sort_by(|a, b| a.total_cmp(b));
    unique_event_times.push(f64::INFINITY);

    let mut density_vec = DVector::from_vec(unique_event_times.clone())
        .map(|_| 1.0 / unique_event_times.len() as f64);

    let weight_matrix = match weights {
        Some(x) => DVector::from_vec(x),
        None => DVector::from_element(events.len(), 1_f64),
    };

    // get indicators of censoring set at current time point
    let dm = DMatrix::from_fn(events.len(), unique_event_times.len(), |i, j| {
        let surv = events.get(i).unwrap();
        let event_time = unique_event_times.get(j).unwrap();
        if surv.get_exit_l() <= *event_time && surv.get_exit_time() >= *event_time {
            return 1.0;
        }

        return 0.0;
    });

    // TODO: get indicators of truncation set at current time point

    // loop here
    let mut tol = 1e9;
    while tol > 1e-9 {
        (tol, density_vec) = km_helper(&dm, &density_vec, &weight_matrix);
    }

    // TODO: variance estimation

    return SurvResult::new_result(unique_event_times, density_vec);
